"use client";

import { useEffect, useRef, useState, type ChangeEvent, type CSSProperties } from "react";
import styles from "./notch-demo.module.css";

const actions = [
  "Quick Actions",
  "Music",
  "Calendar",
  "Reminders",
  "Notifications",
  "Tools",
];

const WALLPAPER_KEY = "mybuddy-web-demo-wallpaper";

function Spider() {
  return (
    <svg
      className={styles.spider}
      viewBox="0 0 46 32"
      fill="none"
      aria-hidden="true"
    >
      <path className={styles.web} d="M23 0v5" />
      <g className={styles.swing}>
        <g className={styles.legs}>
          <path d="M19 13Q13 8 10 10M18 15Q11 12 8 15M18 17Q11 18 10 21M20 19Q16 23 15 25M27 13Q33 8 36 10M28 15Q35 12 38 15M28 17Q35 18 36 21M26 19Q30 23 31 25" />
        </g>
        <ellipse
          className={styles.body}
          cx="23"
          cy="19"
          rx="5.1"
          ry="4.1"
        />
        <circle className={styles.head} cx="23" cy="12.5" r="4.8" />
        <circle className={styles.eye} cx="21.4" cy="12.2" r=".85" />
        <circle className={styles.eye} cx="24.6" cy="12.2" r=".85" />
        <path className={styles.smile} d="M21.5 14.2q1.5 1.2 3 0" />
      </g>
      <path className={styles.twinkle} d="M40 8v5m-2.5-2.5h5M7 22v3m-1.5-1.5h3" />
    </svg>
  );
}

type NotchDemoProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
};

export default function NotchDemo({
  open,
  onOpenChange,
}: NotchDemoProps) {
  // Do not read the current time during render. Next.js prerenders this
  // Client Component, so the server and browser could otherwise get
  // different values on their first render.
  const [now, setNow] = useState<Date | null>(null);
  const [wallpaper, setWallpaper] = useState("");
  const [spider, setSpider] = useState(true);
  const [clock, setClock] = useState(false);
  const root = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const tick = () => setNow(new Date());

    tick();
    const timerId = window.setInterval(tick, 1000);

    try {
      setWallpaper(window.localStorage.getItem(WALLPAPER_KEY) || "");
    } catch {
      // Storage may be unavailable; the demo still works for this session.
    }

    return () => window.clearInterval(timerId);
  }, []);

  useEffect(() => {
    if (!open) return;

    const handlePointerDown = (event: PointerEvent) => {
      if (root.current && !root.current.contains(event.target as Node)) {
        onOpenChange(false);
      }
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onOpenChange(false);
    };

    window.addEventListener("pointerdown", handlePointerDown);
    window.addEventListener("keydown", handleKeyDown);

    return () => {
      window.removeEventListener("pointerdown", handlePointerDown);
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [open, onOpenChange]);

  function choosePhoto(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];

    if (!file || !file.type.startsWith("image/")) return;

    const reader = new FileReader();

    reader.onload = () => {
      const value = typeof reader.result === "string" ? reader.result : "";

      setWallpaper(value);

      try {
        window.localStorage.setItem(WALLPAPER_KEY, value);
      } catch {
        // Keep the selected image in component state if storage is full.
      }
    };

    reader.readAsDataURL(file);
    event.target.value = "";
  }

  const time = now
    ? new Intl.DateTimeFormat([], {
        hour: "numeric",
        minute: "2-digit",
      }).format(now)
    : "--:--";

  const greeting = now
    ? now.getHours() >= 17 || now.getHours() < 5
      ? "Working late"
      : now.getHours() >= 12
        ? "Good afternoon"
        : "Good morning"
    : "Welcome";

  const dateLabel = now
    ? new Intl.DateTimeFormat([], {
        weekday: "long",
        day: "numeric",
        month: "long",
      }).format(now)
    : "Your day";

  const capsuleStyle = wallpaper
    ? ({ "--wallpaper": `url("${wallpaper}")` } as CSSProperties)
    : undefined;

  const panelStyle = wallpaper
    ? { backgroundImage: `url("${wallpaper}")` }
    : undefined;

  return (
    <div className={styles.root} ref={root}>
      <button
        className={styles.capsule}
        style={capsuleStyle}
        onClick={() => onOpenChange(!open)}
        aria-expanded={open}
        aria-label={open ? "Collapse MyBuddy demo" : "Expand MyBuddy demo"}
      >
        {spider && (
          <span className={styles.mark}>
            <Spider />
          </span>
        )}

        {!clock ? (
          <span className={styles.caption}>
            just vibing<span>...</span>
          </span>
        ) : (
          <time className={styles.clock}>{time}</time>
        )}

        <span className={styles.chevron} aria-hidden="true">
          {open ? "⌃" : "⌄"}
        </span>
      </button>

      {open && (
        <section
          className={styles.panel}
          aria-label="Interactive MyBuddy preview"
          style={panelStyle}
        >
          <div className={styles.panelTop}>
            <div>
              <p className={styles.date}>{dateLabel}</p>
              <h2>{greeting}</h2>
              <p className={styles.status}>{time} · You’re all caught up</p>
            </div>

            <button
              className={styles.close}
              onClick={() => onOpenChange(false)}
              aria-label="Close demo"
            >
              ×
            </button>
          </div>

          <p className={styles.tip}>
            <span>TIP</span>
            Launch a favorite app without leaving what you’re doing.
          </p>

          <nav className={styles.actionList} aria-label="MyBuddy features">
            {actions.map((action, index) => (
              <button key={action} type="button">
                <span className={styles.actionIcon} aria-hidden="true">
                  {["⌕", "♫", "▦", "◷", "◉", "⌘"][index]}
                </span>
                {action}
              </button>
            ))}
          </nav>

          <div className={styles.bottom}>
            <label className={styles.photoButton} htmlFor="mybuddy-demo-photo">
              Choose wallpaper
            </label>

            <input
              id="mybuddy-demo-photo"
              className={styles.fileInput}
              type="file"
              accept="image/*"
              onChange={choosePhoto}
            />

            {wallpaper && (
              <button
                className={styles.photoButton}
                type="button"
                onClick={() => {
                  setWallpaper("");

                  try {
                    window.localStorage.removeItem(WALLPAPER_KEY);
                  } catch {
                    // Ignore unavailable storage.
                  }
                }}
              >
                Remove
              </button>
            )}

            <button
              className={styles.toggle}
              type="button"
              aria-pressed={spider}
              onClick={() => setSpider(!spider)}
            >
              <i className={spider ? styles.on : ""} />
              Spider
            </button>

            <button
              className={styles.toggle}
              type="button"
              aria-pressed={clock}
              onClick={() => setClock(!clock)}
            >
              <i className={clock ? styles.on : ""} />
              Clock
            </button>
          </div>
        </section>
      )}
    </div>
  );
}